class SkillProvider(CapabilityProvider):
    """将 SkillManager 包装为 CapabilityProvider。"""

    def __init__(self, skill_manager, skill_name: str, manifest: dict = None):
        self._manager = skill_manager
        self._name = skill_name
        self._manifest = manifest or {}

    def describe(self) -> CapabilityDescriptor:
        return CapabilityDescriptor(
            kind=CapabilityKind.SKILL,
            name=self._name,
            version=self._manifest.get('version', '1.0.0'),
            description=self._manifest.get('description', ''),
            source=self._manifest.get('source', 'builtin'),
            metadata={
                'intents': [c.get('intent', '')
                            for c in self._manifest.get('applicable_when', [])],
            },
        )

    def invoke_sync(self, **kwargs) -> dict:
        return self._manager.execute_skill(self._name, kwargs)


class MetaSkillProvider(CapabilityProvider):
    """将 MetaSkillRegistry 包装为 CapabilityProvider。"""

    def __init__(self, registry, metaskill_name: str, manifest: dict = None):
        self._registry = registry
        self._name = metaskill_name
        self._manifest = manifest or {}

    def describe(self) -> CapabilityDescriptor:
        return CapabilityDescriptor(
            kind=CapabilityKind.METASKILL,
            name=self._name,
            version=self._manifest.get('version', '1.0.0'),
            description=self._manifest.get('description', ''),
            source=self._manifest.get('source', 'builtin'),
            inputs=self._manifest.get('inputs', {}),
            outputs=self._manifest.get('outputs', {}),
            metadata={'zero_llm': self._manifest.get('zero_llm', True)},
        )

    def invoke_sync(self, **kwargs) -> dict:
        return self._registry.run_metaskill(self._name, kwargs)


class ToolProvider(CapabilityProvider):
    """将 ToolRegistry 的单个工具包装为 CapabilityProvider。"""

    def __init__(self, tool_registry, tool_name: str,
                 description: str = '', methods: list = None):
        self._registry = tool_registry
        self._name = tool_name
        self._description = description
        self._methods = methods or []

    def describe(self) -> CapabilityDescriptor:
        return CapabilityDescriptor(
            kind=CapabilityKind.TOOL,
            name=self._name,
            description=self._description,
            source='builtin',
            metadata={'methods': self._methods},
        )

    def invoke_sync(self, **kwargs) -> dict:
        method = kwargs.pop('method', self._methods[0] if self._methods else '')
        return self._registry.call(self._name, method, kwargs)

    def health_check(self) -> dict:
        module = self._registry._loaded.get(self._name)
        return {
            'status': 'ok' if module else 'unloaded',
            'name': self._name,
        }


class CommandProvider(CapabilityProvider):
    """将 CommandRegistry 的命令包装为 CapabilityProvider。"""

    def __init__(self, command_registry, command_name: str,
                 description: str = '', require_llm: bool = False):
        self._registry = command_registry
        self._name = command_name
        self._description = description
        self._require_llm = require_llm

    def describe(self) -> CapabilityDescriptor:
        return CapabilityDescriptor(
            kind=CapabilityKind.COMMAND,
            name=self._name,
            description=self._description,
            source='builtin',
            metadata={'require_llm': self._require_llm},
        )

    def invoke_sync(self, **kwargs) -> dict:
        app = kwargs.get('app')
        return self._registry.execute(self._name, app=app)


class A2AProvider(CapabilityProvider):
    """将远程 Agent 能力包装为 CapabilityProvider。"""

    def __init__(self, caller, agent_card: dict):
        self._caller = caller
        self._card = agent_card

    def describe(self) -> CapabilityDescriptor:
        agent_id = self._card.get('agent_id', 'unknown')
        return CapabilityDescriptor(
            kind=CapabilityKind.A2A_AGENT,
            name='agent:%s' % agent_id,
            description='远程 Agent: %s' % self._card.get('name', agent_id),
            source='remote',
            metadata={
                'agent_id': agent_id,
                'host': self._card.get('host', ''),
                'port': self._card.get('port', 0),
                'skills': [s['name'] for s in self._card.get('skills', [])],
            },
        )

    def invoke_sync(self, **kwargs) -> dict:
        agent_id = self._card.get('agent_id', '')
        instruction = kwargs.get('instruction', kwargs.get('user_instruction', ''))
        return self._caller.call(agent_id, instruction)

    def health_check(self) -> dict:
        agent_id = self._card.get('agent_id', '')
        try:
            result = self._caller.ping(agent_id)
            return {'status': 'ok' if result else 'unreachable',
                    'name': 'agent:%s' % agent_id}
        except Exception as e:
            return {'status': 'error', 'name': 'agent:%s' % agent_id,
                    'error': str(e)}


