class CapabilityRegistry:
    """统一能力注册表 — 所有能力原语的公共基座。

    用法：
        registry = CapabilityRegistry()

        # 注册
        registry.register(SkillProvider(skill_mgr, 'data_analysis'))
        registry.register(ToolProvider(tool_reg, 'shell', methods=['exec']))

        # 发现
        all_caps = registry.discover()
        skills_only = registry.discover(kind=CapabilityKind.SKILL)

        # 调用
        result = await registry.invoke('data_analysis', user_instruction='...')

        # 统计
        counts = registry.counts()
    """

    def __init__(self):
        self._providers: dict[str, CapabilityProvider] = {}
        self._hooks: dict[str, list] = {
            'before_register': [],
            'after_register': [],
            'before_invoke': [],
            'after_invoke': [],
        }

    # ─────────────────────────────────────────
    # 注册 / 注销
    # ─────────────────────────────────────────

    def register(self, provider: CapabilityProvider) -> bool:
        """注册一个能力提供者。

        Args:
            provider: CapabilityProvider 实例

        Returns:
            True 表示成功
        """
        try:
            desc = provider.describe()
        except Exception:
            logger.exception('获取能力描述失败')
            return False

        # before_register 钩子
        for hook in self._hooks['before_register']:
            try:
                hook(desc)
            except Exception:
                logger.exception('before_register 钩子异常（已隔离）')

        self._providers[desc.name] = provider

        # after_register 钩子
        for hook in self._hooks['after_register']:
            try:
                hook(desc)
            except Exception:
                logger.exception('after_register 钩子异常（已隔离）')

        logger.info('注册能力: [%s] %s (v%s, %s)',
                    desc.kind.value, desc.name, desc.version, desc.source)
        return True

    def unregister(self, name: str) -> bool:
        """注销一个能力。"""
        if name in self._providers:
            del self._providers[name]
            logger.info('注销能力: %s', name)
            return True
        return False

    # ─────────────────────────────────────────
    # 发现
    # ─────────────────────────────────────────

    def discover(self, kind: CapabilityKind = None,
                 include_disabled: bool = False) -> list:
        """发现已注册能力。

        Args:
            kind: 按类型过滤（None 返回全部）
            include_disabled: 是否包含已禁用的

        Returns:
            CapabilityDescriptor 列表
        """
        result = []
        for provider in self._providers.values():
            try:
                desc = provider.describe()
            except Exception:
                continue
            if kind is not None and desc.kind != kind:
                continue
            if not include_disabled and not desc.enabled:
                continue
            result.append(desc)
        return result

    def discover_dict(self, **kwargs) -> list:
        """discover() 的 dict 版本（用于 API 响应）。"""
        return [d.to_dict() for d in self.discover(**kwargs)]

    def get(self, name: str) -> Optional[CapabilityProvider]:
        """获取单个能力提供者。"""
        return self._providers.get(name)

    def get_descriptor(self, name: str) -> Optional[CapabilityDescriptor]:
        """获取单个能力描述符。"""
        provider = self._providers.get(name)
        if provider:
            try:
                return provider.describe()
            except Exception:
                pass
        return None

    # ─────────────────────────────────────────
    # 调用
    # ─────────────────────────────────────────

    async def invoke(self, name: str, **kwargs) -> dict:
        """异步调用指定能力。

        Args:
            name: 能力名称
            **kwargs: 调用参数

        Returns:
            调用结果 dict
        """
        provider = self._providers.get(name)
        if not provider:
            return {'success': False, 'error': '能力 %s 未找到' % name}

        desc = provider.describe()
        if not desc.enabled:
            return {'success': False, 'error': '能力 %s 已禁用' % name}

        # before_invoke 钩子
        for hook in self._hooks['before_invoke']:
            try:
                hook(name, kwargs)
            except Exception:
                logger.exception('before_invoke 钩子异常（已隔离）')

        # 执行
        t_start = time.monotonic()
        try:
            result = await provider.invoke(**kwargs)
        except Exception as e:
            logger.exception('能力 %s 调用异常', name)
            result = {'success': False, 'error': str(e)}
        elapsed_ms = (time.monotonic() - t_start) * 1000

        # after_invoke 钩子
        for hook in self._hooks['after_invoke']:
            try:
                hook(name, result)
            except Exception:
                logger.exception('after_invoke 钩子异常（已隔离）')

        logger.info('[CapabilityRegistry] invoke %s -> %s %.0fms',
                    name,
                    'ok' if result.get('success', True) else 'failed',
                    elapsed_ms)
        return result

    def invoke_sync(self, name: str, **kwargs) -> dict:
        """同步调用指定能力。"""
        provider = self._providers.get(name)
        if not provider:
            return {'success': False, 'error': '能力 %s 未找到' % name}

        desc = provider.describe()
        if not desc.enabled:
            return {'success': False, 'error': '能力 %s 已禁用' % name}

        try:
            return provider.invoke_sync(**kwargs)
        except Exception as e:
            logger.exception('能力 %s 同步调用异常', name)
            return {'success': False, 'error': str(e)}

    # ─────────────────────────────────────────
    # 健康检查
    # ─────────────────────────────────────────

    def health_check_all(self) -> dict:
        """对所有已注册能力执行健康检查。

        Returns:
            {name: {status, ...}, ...}
        """
        results = {}
        for name, provider in self._providers.items():
            try:
                results[name] = provider.health_check()
            except Exception as e:
                results[name] = {'status': 'error', 'error': str(e)}
        return results

    # ─────────────────────────────────────────
    # 钩子注册
    # ─────────────────────────────────────────

    def add_hook(self, event: str, handler: Callable):
        """注册生命周期钩子。

        Args:
            event: 事件名（before_register / after_register /
                          before_invoke / after_invoke）
            handler: 回调函数
        """
        if event not in self._hooks:
            raise ValueError('未知钩子事件: %s' % event)
        self._hooks[event].append(handler)

    # ─────────────────────────────────────────
    # 统计
    # ─────────────────────────────────────────

    def counts(self) -> dict:
        """按类型统计已注册能力数量。"""
        result = {k.value: 0 for k in CapabilityKind}
        for provider in self._providers.values():
            try:
                desc = provider.describe()
                result[desc.kind.value] = result.get(desc.kind.value, 0) + 1
            except Exception:
                pass
        return result

    def __len__(self):
        return len(self._providers)

    def __repr__(self):
        return '<CapabilityRegistry total=%d counts=%s>' % (
            len(self), self.counts())


# ─────────────────────────────────────────
# 批量注册辅助函数
# ─────────────────────────────────────────

def register_all_capabilities(
    registry: CapabilityRegistry,
    skill_manager=None,
    metaskill_registry=None,
    tool_registry=None,
    command_registry=None,
    a2a_caller=None,
) -> int:
    """从现有注册表批量注册到统一能力注册表。

    Args:
        registry: 目标 CapabilityRegistry
        skill_manager: SkillManager 实例
        metaskill_registry: MetaSkillRegistry 实例
        tool_registry: ToolRegistry 实例
        command_registry: CommandRegistry 实例
        a2a_caller: A2ACaller 实例

    Returns:
        注册数量
    """
    count = 0

    # 技能
    if skill_manager:
        for skill_info in skill_manager.list_skills():
            name = skill_info['name']
            skill_data = skill_manager.load_skill(name)
            manifest = skill_data.get('manifest', {}) if skill_data else {}
            manifest['source'] = skill_info.get('source', 'builtin')
            provider = SkillProvider(skill_manager, name, manifest)
            if registry.register(provider):
                count += 1

    # 元技能
    if metaskill_registry:
        for ms_info in metaskill_registry.list_metaskills():
            name = ms_info['name']
            ms_data = metaskill_registry.get_metaskill(name)
            manifest = ms_data.get('manifest', {}) if ms_data else {}
            manifest['source'] = ms_info.get('source', 'builtin')
            provider = MetaSkillProvider(metaskill_registry, name, manifest)
            if registry.register(provider):
                count += 1

    # 工具
    if tool_registry:
        for tool_info in tool_registry.list_tools():
            name = tool_info['name']
            provider = ToolProvider(
                tool_registry, name,
                description=tool_info.get('description', ''),
                methods=tool_info.get('methods', []))
            if registry.register(provider):
                count += 1

    # 指令
    if command_registry:
        for cmd_info in command_registry.list_commands():
            name = cmd_info['name']
            provider = CommandProvider(
                command_registry, name,
                description=cmd_info.get('description', ''),
                require_llm=cmd_info.get('require_llm', False))
            if registry.register(provider):
                count += 1

    logger.info('批量注册完成: %d 个能力', count)
    return count
